import {createCalendar} from './calendar-ui.js?v=34';
import {documentReferences} from './inventory-model.js?v=17';
import {ensureProfiles} from './workspace-model.js?v=34';

export function createWorkspace(a){
  const {esc,money,date,fullDate,icon,btn,pill,link,panel,empty}=a;
  let homeMode=['overview','calendar','control'].includes(location.hash.split('/')[1])?location.hash.split('/')[1]:'control';
  let profileTab='identity';
  const calendar=createCalendar(a);
  const modeTabs=()=>`<div class="home-views" aria-label="Visões da Home"><button data-home-view="control" aria-pressed="${homeMode==='control'}" class="${homeMode==='control'?'active':''}">${icon('task')}Pendências</button><button data-home-view="calendar" aria-pressed="${homeMode==='calendar'}" class="${homeMode==='calendar'?'active':''}">${icon('calendar')}Calendário</button><button data-home-view="overview" aria-pressed="${homeMode==='overview'}" class="${homeMode==='overview'?'active':''}">${icon('flow')}Visão geral</button></div>`;
  function home(overview){if(homeMode==='control')return a.titleBlock('Home','Obrigações, tarefas e desvios com uma próxima ação.',modeTabs(),'Seu painel de controle')+(a.controlPanel?.()||'');return (a.controlSummary?.()||'')+(homeMode==='overview'?`<div class="overview-viewbar"><span>Seu painel de saldos e acompanhamento</span>${modeTabs()}</div>`+overview():calendar.render(modeTabs()));}

  function currentCompany(){ensureProfiles(a.state);return a.get('companies',a.company)}
  function profileDocs(){return a.scope('documents').filter(d=>documentReferences(a.state,d).some(r=>r.kind==='company'&&r.id===a.company&&r.purpose==='documentation'))}
  function profile(){const c=currentCompany(),p=c.profile,docs=profileDocs();return a.titleBlock('Perfil da empresa','Cadastro, documentos e condições do contexto selecionado.',btn('Editar perfil','data-open="company-profile-edit"','primary','company'),'Seu contexto')+`<section class="profile-hero"><div class="profile-monogram">${esc(c.short)}</div><div class="profile-identity"><span class="eyebrow">Empresa selecionada</span><h2>${esc(c.name)}</h2><p>${esc(c.activity)}</p><div class="profile-tags">${pill(c.city||'Localização a informar')}${pill(p.organization||'Natureza a definir')}</div></div><div class="profile-context-note">${icon('company')}<p>Para mudar de empresa,<br>use o seletor lateral.</p></div></section><div class="profile-tabs" aria-label="Seções do perfil">${[['identity','Cadastro','company'],['documents','Documentação','file'],['conditions','Condições específicas','task']].map(([id,label,ico])=>`<button data-profile-tab="${id}" class="${profileTab===id?'active':''}" aria-pressed="${profileTab===id}">${icon(ico)}${label}${id==='documents'?`<span>${docs.length}</span>`:id==='conditions'?`<span>${p.conditions?.length||0}</span>`:''}</button>`).join('')}</div>${profileTab==='identity'?profileIdentity(c):profileTab==='documents'?profileDocuments(c):profileConditions(c)}`}
  function profileIdentity(c){const p=c.profile;return `<div class="profile-body-grid">${panel('Identificação e responsáveis','Informações desta empresa',`<dl class="profile-fields"><div><dt>Nome</dt><dd>${esc(c.name)}</dd></div><div><dt>Identificação fiscal / CNPJ</dt><dd>${esc(p.registration||'Não informado')}</dd></div><div><dt>Atividade</dt><dd>${esc(c.activity)}</dd></div><div><dt>Localização</dt><dd>${esc(c.city||'A informar')}</dd></div><div><dt>Responsável pela organização</dt><dd>${esc(p.responsible||'A definir')}</dd></div><div><dt>Contabilidade</dt><dd>${esc(p.accounting||'A definir')}</dd></div><div><dt>Condição tributária informada</dt><dd>${esc(p.taxStatus||'A confirmar')}</dd></div><div><dt>Natureza da operação</dt><dd>${esc(p.organization||'A definir')}</dd></div></dl>`)}<div>${panel('Contexto da operação','O que orienta a organização',`<div class="profile-purpose"><p>${esc(p.purpose||'Descreva a operação da empresa para orientar os documentos e as próximas ações.')}</p>${btn('Editar informações','data-open="company-profile-edit"','','plus')}</div>`)}<section class="profile-shortcuts">${[['Ativos','assets','assets','asset'],['Contratos','contracts','contracts','contract'],['Documentos','documents','documents','file'],['Tarefas abertas','tasks','tasks','task']].map(([label,key,page,ico])=>`<button data-go="${page}">${icon(ico)}<strong>${a.scope(key).filter(x=>key!=='tasks'||!x.done).length}</strong><span>${label}</span></button>`).join('')}</section></div></div>${panel('Contas financeiras da empresa','As contas acompanham o contexto selecionado.',`<div class="profile-accounts">${a.scope('accounts').map(x=>`<button data-profile-account="${x.id}">${icon('wallet')}<span><b>${esc(x.name)}</b><small>${esc(x.label)}</small></span><span class="textbtn">Ver fluxo ${icon('chevron')}</span></button>`).join('')}</div>`)}<p class="profile-footnote">Identificação bancária importada. Complete e confira os demais dados cadastrais da empresa.</p>`}
  function profileDocuments(c){const docs=profileDocs();return `<div class="profile-section-title"><div><h2>Documentação da empresa</h2><p>Cadastro, documentos societários, certidões e orientações internas.</p></div><div class="profile-document-actions">${btn('Vincular do acervo','data-open="profile-link-document"','','link')}${btn('Enviar documento',`data-open="newdoc" data-id="profile:${c.id}"`,'primary','plus')}</div></div><div class="profile-document-list">${docs.map(d=>`<button data-open="document" data-id="${d.id}" class="profile-document"><span class="profile-document-icon">${icon('file')}</span><span><b>${esc(d.name)}</b><small>${esc(d.type)} · ${fullDate(d.date)} · ${esc(d.source)}</small></span>${pill(d.status,d.status==='Revisado'?'green':'amber')}${icon('chevron')}</button>`).join('')||empty('Comece pela documentação da empresa','Envie um arquivo ou vincule um documento que já está no acervo.')}</div><div class="profile-doc-hint">${icon('info')}<p>Esta seção reúne os documentos institucionais. O acervo completo continua em <button class="textbtn" data-go="documents">Documentos</button>, incluindo cobranças, recibos e comprovantes.</p></div>`}
  function profileConditions(c){const p=c.profile;return `<div class="profile-section-title"><div><h2>Condições específicas</h2><p>Orientações e particularidades que precisam acompanhar a empresa.</p></div>${btn('Adicionar condição','data-open="company-condition"','primary','plus')}</div><div class="condition-list">${(p.conditions||[]).map((r,i)=>`<article class="condition-card"><div class="condition-number">${String(i+1).padStart(2,'0')}</div><div><div class="condition-meta">${pill(r.area)}<span>Responsável: ${esc(r.owner)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p></div>${btn('Editar',`data-open="company-condition" data-id="${r.id}"`)}</article>`).join('')||empty('Nenhuma condição cadastrada','Registre regras de conferência, exceções contratuais ou orientações para a contabilidade.')}</div><div class="profile-doc-hint">${icon('info')}<p>Estas condições são referências de conferência nesta prévia. Cadastrá-las não cria obrigações nem executa regras automaticamente.</p></div>`}
  function dialog(kind,id){const c=currentCompany(),p=c.profile;
    if(kind==='company-profile-edit')return {heading:'Perfil da empresa · editar',body:a.formShell('Informações da empresa','Atualize o cadastro deste contexto. Seus documentos e vínculos serão preservados.',`<label>Nome da empresa<input name="name" required maxlength="100" value="${esc(c.name)}"></label><div class="formrow"><label>Identificação fiscal / CNPJ<input name="registration" maxlength="30" placeholder="A informar" value="${esc(p.registration||'')}"></label><label>Cidade / estado<input name="city" maxlength="100" value="${esc(c.city)}"></label></div><label>Atividade<input name="activity" required maxlength="150" value="${esc(c.activity)}"></label><label>Natureza da operação<input name="organization" maxlength="100" value="${esc(p.organization)}"></label><div class="formrow"><label>Responsável<input name="responsible" maxlength="100" value="${esc(p.responsible)}"></label><label>Contabilidade<input name="accounting" maxlength="100" value="${esc(p.accounting)}"></label></div><label>Condição tributária informada<input name="taxStatus" maxlength="100" value="${esc(p.taxStatus)}" placeholder="Informação a confirmar com a contabilidade"></label><label>Contexto da operação<textarea name="purpose" maxlength="1000">${esc(p.purpose)}</textarea></label>`,'company-profile-edit',c.id,'Salvar perfil')};
    if(kind==='company-condition'){const r=p.conditions?.find(r=>r.id===id)||{};return {heading:'Perfil da empresa · condição',body:a.formShell(r.id?'Editar condição':'Adicionar condição','Registre uma orientação específica e quem deve acompanhá-la.',`<label>Título<input name="title" required maxlength="130" value="${esc(r.title||'')}"></label><div class="formrow"><label>Assunto<select name="area">${['Documentos','Contratos','Pagamentos','Contabilidade','Operação'].map(t=>`<option ${r.area===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Responsável<input name="owner" required maxlength="100" value="${esc(r.owner||'Você')}"></label></div><label>Condição ou orientação<textarea name="description" required maxlength="1400" placeholder="Descreva como conferir, quais exceções existem e onde encontrar a origem.">${esc(r.description||'')}</textarea></label>`,'company-condition',id||'','Salvar condição')};}
    if(kind==='profile-link-document')return {heading:'Perfil da empresa · vincular documento',body:a.formShell('Vincular documento do acervo','O arquivo mantém seu registro e passa a aparecer também no perfil.',`<label>Documento<select name="document" required><option value="">Selecione um documento desta empresa</option>${a.scope('documents').filter(d=>d.profileCompany!==c.id).map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label>`,'profile-link-document',c.id,'Vincular ao perfil')};
    return null;
  }
  function click(d,event){
    if(calendar.click(d,event))return true;
    if(d.homeView){if(homeMode==='calendar'&&d.homeView==='overview')(a.setCalendarFocus||a.selectDate)(calendar.selection.focus);homeMode=d.homeView;history.replaceState(null,'','#home/'+homeMode);a.render();return true;}
    if(d.profileTab){profileTab=d.profileTab;a.render();return true;}
    if(d.profileAccount){a.setAccount(d.profileAccount);a.navigate('flow');return true;}
    return false;
  }
  function change(e){return calendar.change(e);}
  function submit(form,data){const kind=form.dataset.form,id=form.dataset.id,v=k=>String(data.get(k)||'').trim(),c=currentCompany();
    if(kind==='company-profile-edit'){if(id!==c.id)return true;c.name=v('name');c.city=v('city');c.activity=v('activity');c.short=c.name.split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase();for(const field of ['registration','organization','responsible','accounting','taxStatus','purpose'])c.profile[field]=v(field);a.save();a.closeAll();a.render();a.toast('Perfil atualizado nesta empresa.');return true}
    if(kind==='company-condition'){c.profile.conditions??=[];const existing=c.profile.conditions.find(r=>r.id===id),values={title:v('title'),area:v('area'),owner:v('owner'),description:v('description')};if(existing)Object.assign(existing,values);else c.profile.conditions.push({...values,id:'condition-'+crypto.randomUUID()});profileTab='conditions';a.save();a.closeAll();a.render();a.toast('Condição registrada no perfil, sem criar lançamentos.');return true}
    if(kind==='profile-link-document'){const d=a.scope('documents').find(d=>d.id===v('document'));if(!d){a.toast('Escolha um documento desta empresa.');return true}d.profileCompany=c.id;profileTab='documents';a.save();a.closeAll();a.render();a.toast('Documento vinculado ao perfil. O original foi preservado.');return true}
    return false;
  }
  return {home,profile,dialog,click,change,submit,calendarPointer:calendar.pointer,calendarKeydown:e=>homeMode==='calendar'&&location.hash.startsWith('#home')&&calendar.keydown(e),selectCalendarDate:calendar.externalDate,get calendarSelection(){return calendar.selection;},setHomeMode(mode){homeMode=['overview','calendar','control'].includes(mode)?mode:'control'}};
}
